     "natureza": "proposta",
     "pagina": 61,
     "termo": "clima",
     "texto": "Frente ao crescente risco associado às mudanças climáticas, buscaremos implementar um programa nacional de resiliência climática no campo, ampliando as áreas irrigadas, promovendo a conservação dos solos, incentivando a agricultura de precisão e o plantio direto, além de modernizar ainda mais o monitoramento meteorológico e os sistemas de alerta precoce para os produtores.",
     "inicio": 48,
     "fim": 58,
     "fraseInicio": 0,
     "fraseFim": 375,
     "origem": "paragrafo",
