     "tema": "adaptacao",
     "natureza": "diagnostico",
     "pagina": 30,
     "termo": "clima",
     "texto": "Entretanto, setores tradicionais enfrentam desafios relevantes. A pecuária extensiva do Pampa convive com a perda de competitividade, enquanto a cadeia do leite sofre com a instabilidade dos preços e a concorrência de produtos importados. Ao mesmo tempo, as mudanças climáticas tornam urgente a incorporação de novas tecnologias, o manejo sustentável do solo e dos rebanhos e o aumento da eficiência e da resiliência produtiva.",
     "inicio": 267,
     "fim": 277,
     "fraseInicio": 239,
     "fraseFim": 427,
     "origem": "paragrafo",
